import (
    "fmt"
    "strings"
)

func parseTokens(input string) []string {
    var tokens []string
    var current strings.Builder
    inQuotes := false

    for _, r := range input {
        if r == '"' {
            inQuotes = !inQuotes
            continue
        }
        if r == ' ' && !inQuotes {
            if current.Len() > 0 {
                tokens = append(tokens, current.String())
                current.Reset()
            }
        } else {
            current.WriteRune(r)
        }
    }
    if current.Len() > 0 {
        tokens = append(tokens, current.String())
    }
    return tokens
}
